#!/usr/bin/env bash
# Partie « Contenu éditorial » : carte des entités et parcours (constructeur de pages, réglages du site).
# Analyse : composants serveur affichés, gabarits (layout), filtres sur relation.
# Prérequis : apply-carte-domaine.sh.
# Usage (racine du repo) : bash apply-carte-contenu.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null | grep -qF "Un visiteur lit la page"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Un visiteur consulte l'agenda" "apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-carte-domaine.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/src/features/docs/entities/EntityExplorer.tsx" "apps/web/src/features/docs/entities/stories.ts" "scripts/build-procedure-map.mjs" "apps/web/src/features/docs/entities/procedureMap.generated.json")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Un visiteur lit la page" "apps/web/content/docs/dev/contenu/constructeur-de-pages.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/entities"
base64 -d > "apps/web/src/features/docs/entities/procedureMap.generated.json" <<'B64'
